const updateSkill = `-- name: UpdateSkill :one
UPDATE skill SET
    name = COALESCE($2, name),
    description = COALESCE($3, description),
    content = COALESCE($4, content),
    config = COALESCE($5, config),
    updated_at = now()
WHERE id = $1
RETURNING id, workspace_id, name, description, content, config, created_by, created_at, updated_at, plugin_installation_id, scope, owner_user_id
`

type UpdateSkillParams struct {
	ID          pgtype.UUID `json:"id"`
	Name        pgtype.Text `json:"name"`
	Description pgtype.Text `json:"description"`
	Content     pgtype.Text `json:"content"`
	Config      []byte      `json:"config"`
}

func (q *Queries) UpdateSkill(ctx context.Context, arg UpdateSkillParams) (Skill, error) {
	row := q.db.QueryRow(ctx, updateSkill,
		arg.ID,
		arg.Name,
		arg.Description,
		arg.Content,
		arg.Config,
	)
	var i Skill
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.Content,
		&i.Config,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.PluginInstallationID,
		&i.Scope,
		&i.OwnerUserID,
	)
	return i, err
}

const upsertSkillFile = `-- name: UpsertSkillFile :one
INSERT INTO skill_file (skill_id, path, content)
VALUES ($1, $2, $3)
ON CONFLICT (skill_id, path) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = now()
RETURNING id, skill_id, path, content, created_at, updated_at
`

type UpsertSkillFileParams struct {
	SkillID pgtype.UUID `json:"skill_id"`
	Path    string      `json:"path"`
	Content string      `json:"content"`
}

func (q *Queries) UpsertSkillFile(ctx context.Context, arg UpsertSkillFileParams) (SkillFile, error) {
	row := q.db.QueryRow(ctx, upsertSkillFile, arg.SkillID, arg.Path, arg.Content)
	var i SkillFile
	err := row.Scan(
		&i.ID,
		&i.SkillID,
		&i.Path,
		&i.Content,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
